def BoundStates(x, Emax, Estep):
    '''Input
    x: coordinate x; a float or a 1D array of float
    Emax: maximum energy of a bound state; a float
    Estep: energy step size; a float
    Output
    bound_states: a list, each element is a tuple containing the principal quantum number (an int) and energy (a float)
    '''

    step = x[1] - x[0]

    bound_states = []

    n = 0
    E = 0.0

    def get_bc(n):
        if n % 2 == 0:
            return (1.0, 0.0)
        else:
            return (0.0, 1.0)

    u_b, up_b = get_bc(n)

    def count_nodes(En):
        u = Solve_Schrod(x, En, u_b, up_b, step)
        return count_sign_changes(u)

    prev_nodes = count_nodes(0.0)

    E_values = np.arange(Estep, Emax + Estep, Estep)

    prev_E = 0.0

    for E in E_values:
        current_nodes = count_nodes(E)

        if current_nodes != prev_nodes:
            # a bound state has been found between prev_E and E
            def node_diff(En):
                nodes = count_nodes(En)
                return nodes - n - 0.5

            try:
                E_root = optimize.brentq(node_diff, prev_E, E)
            except ValueError:
                E_root = (prev_E + E) / 2.0

            bound_states.append((n, E_root))

            n += 1
            u_b, up_b = get_bc(n)

            prev_nodes = count_nodes(E)
        else:
            prev_nodes = current_nodes

        prev_E = E

    return bound_states
